        var page: PaginatedCurrencySummaryList =
            currencyList(clientConfig, limit, offset, q, options)
        while (true) {
            for (item in page.results.orEmpty()) {
                if (!yieldFn(item)) return
            }
            val nextUrl = page.next ?: return
            page =
                SdkClient.request<PaginatedCurrencySummaryList>(
                        SdkClient.RequestSpec(
                            method = "GET",
                            path = nextUrl,
                            operationId = "currencyList",
                            config = clientConfig,
                            options = options,
                        )
                    )
                    .data
        }
    }

    data class CurrencyListPage(
        val data: PaginatedCurrencySummaryList,
        val items: List<CurrencySummary>,
        val hasMore: Boolean,
    )

    fun currencyListPages(
        clientConfig: ClientConfig,
        limit: Int? = null,
        offset: Int? = null,
        q: String? = null,
        options: RequestOptions? = null,
        yieldPage: (CurrencyListPage) -> Boolean,
    ) {
        var page: PaginatedCurrencySummaryList =
            currencyList(clientConfig, limit, offset, q, options)
        while (true) {
            val items = page.results.orEmpty()
            val nextUrl = page.next
            val hasMore = !nextUrl.isNullOrEmpty()
            if (!yieldPage(CurrencyListPage(page, items, hasMore))) return
            if (!hasMore) return
            page =
                SdkClient.request<PaginatedCurrencySummaryList>(
                        SdkClient.RequestSpec(
                            method = "GET",
                            path = nextUrl,
                            operationId = "currencyList",
                            config = clientConfig,
                            options = options,
                        )
                    )
                    .data
        }
    }

    /**
     * Retrieves a single currency used to buy items, including its localized names. Use `id` to
     * identify the currency whose details you want to inspect.
     *
     * Currencies used to buy items.
     *
     * @param id This parameter can be a string or an integer.
     */
    fun currencyRetrieve(
        clientConfig: ClientConfig,
        id: String,
        options: RequestOptions? = null,
    ): CurrencyDetail {
        return SdkClient.request<CurrencyDetail>(
                SdkClient.RequestSpec(
                    "GET",
                    "/api/v2/currency/${SdkClient.encodePathSegment(id)}/",
                    config = clientConfig,
                    operationId = "currencyRetrieve",
                    decoder = SdkClient.ResponseDecoder.JSON,
                    options = options,
                )
            )
            .data
    }
